          type: 'string',
          description: 'Substring to match against item names (case-insensitive).'
        },
        offset: {
          type: 'integer',
          minimum: 0,
          default: DEFAULT_OFFSET,
          description: 'Number of matching rows to skip before returning results.'
        },
        limit: {
          type: 'integer',
          minimum: MIN_LIMIT,
          maximum: MAX_LIMIT,
          default: DEFAULT_LIMIT,
          description: `Maximum number of rows to return (${MIN_LIMIT}-${MAX_LIMIT}).`
        }
      },
      required: ['query']
    }
  }];
}

export async function callTool(name, args = {}) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }

  for (const key of Object.keys(args)) {
    if (!ALLOWED_ARGS.includes(key)) {
      throw new Error(`Unexpected argument: ${key}`);
    }
  }

  const { query } = args;
  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }

  let offset;
  if (args.offset === undefined || args.offset === null) {
    offset = DEFAULT_OFFSET;
  } else if (Number.isInteger(args.offset) && args.offset >= 0) {
    offset = args.offset;
  } else {
    throw new Error('offset must be a non-negative integer');
  }

  let limit;
  if (args.limit === undefined || args.limit === null) {
    limit = DEFAULT_LIMIT;
  } else if (Number.isInteger(args.limit) && args.limit >= MIN_LIMIT && args.limit <= MAX_LIMIT) {
    limit = args.limit;
  } else {
    throw new Error(`limit must be an integer between ${MIN_LIMIT} and ${MAX_LIMIT}`);
  }

  const needle = query.toLowerCase();
  const matches = items.filter(item => item.name.toLowerCase().includes(needle));

  const start = offset;
  const end = offset + limit;
  const page = matches.slice(start, end);

  const result = { items: page };
  if (end < matches.length) {
    result.next_offset = end;
  }

  return {
    content: [{ type: 'text', text: JSON.stringify(result) }]
  };
}

